# =============================================================================
# PANDA  --  SYNTHETIC SRS GENERATOR      *** TEST TOOL -- NOT REAL DATA ***
# =============================================================================
#  ############################################################
#  #  EVERYTHING THIS MODULE WRITES IS FABRICATED.            #
#  #  Every generated file carries a SYNTHETIC banner in its  #
#  #  metadata and 'synthetic' in its sample_name, so a file  #
#  #  from here can never be mistaken for beamline data.      #
#  ############################################################
#
# Why this exists: PANDA's Stages 1-3 had to be built and validated before any
# real theta-2theta tau-series existed. The only real I10 files available are
# XMCD *energy* scans, which have no reflection to integrate. So this module
# fabricates SRS-format theta-2theta scans with KNOWN injected Stokes
# parameters, letting the whole chain be checked against ground truth:
#
#       inject (P1', P2')  ->  write .dat files  ->  Stage 1 reduce
#                          ->  Stage 3a integrate  ->  Stage 3b fit
#                          ->  assert recovered (P1', P2') == injected
#
# It also writes a matching phase-1 logger CSV, so the generated series loads
# through exactly the same path a real one would.
#
# GUI-free, like rsxd_analysis and rsxd_core.
# =============================================================================

from __future__ import annotations

import math
from dataclasses import dataclass, field
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional, Sequence, Tuple

import numpy as np

from rsxd_analysis import VERSION as ANALYSIS_VERSION
from rsxd_core import CSV_COLUMNS, _atomic_write, fmt_gain

VERSION = "v2026-08-08-gain-tracking"

SYNTHETIC_BANNER = "SYNTHETIC DATA GENERATED BY rsxd_synth.py -- NOT A REAL MEASUREMENT"

# Column names the generated theta-2theta files use. The first column is the
# scanned axis, which is what PANDA's default abscissa_column="" resolves to;
# the scaler channels reuse the real I10 names so the default column map in
# panda_config.toml works on synthetic and real files alike.
SYNTH_COLUMNS = ["tth", "mcsh16", "mcsh17", "mcsh18", "mcsh19"]


# =============================================================================
# GROUND TRUTH
# =============================================================================

@dataclass
class SynthPeak:
    """The truth a generated series is built from, and checked against."""
    name: str
    p1: float                       # injected P1' (charge-like > 0, magnetic-like < 0)
    p2: float                       # injected P2'
    centre_deg: float = 30.0        # 2theta of the reflection
    fwhm_deg: float = 0.6
    peak_counts: float = 40000.0    # detector counts at the top of the peak, tau-averaged
    background_counts: float = 500.0
    background_slope: float = 0.0
    i0_counts: float = 500000.0     # monitor counts per point
    energy_eV: float = 707.5
    field_T: float = 0.0
    temperature_K: float = 300.0
    lorentzian_fraction: float = 0.3


# Two ready-made cases covering the physics the discriminator has to separate.
CHARGE_PEAK = SynthPeak(name="charge", p1=+0.82, p2=+0.11,
                        centre_deg=30.0, energy_eV=695.0, peak_counts=60000.0)
MAGNETIC_PEAK = SynthPeak(name="magnetic", p1=-0.74, p2=+0.28,
                          centre_deg=22.5, energy_eV=707.5, peak_counts=9000.0)


# =============================================================================
# PROFILE
# =============================================================================

def _pseudo_voigt(x: np.ndarray, centre: float, fwhm: float, eta: float) -> np.ndarray:
    """
    Unit-height pseudo-Voigt.

    Deliberately NOT the same functional form the Voigt option in
    rsxd_analysis fits. If the generator and the fitter shared a model, the
    self-test would only prove the code is self-consistent. Using a
    pseudo-Voigt here and a true Voigt there means the model-free trapezoid --
    the default and the thing that actually matters -- is being tested against
    a shape it was never told about.
    """
    sigma = fwhm / (2.0 * math.sqrt(2.0 * math.log(2.0)))
    gauss = np.exp(-0.5 * ((x - centre) / sigma) ** 2)
    gamma = fwhm / 2.0
    lorentz = gamma ** 2 / ((x - centre) ** 2 + gamma ** 2)
    return (1.0 - eta) * gauss + eta * lorentz


def expected_area(peak: SynthPeak, tau_deg: float) -> float:
    """
    The integrated intensity (in normalised units, I = Im/I0) this generator
    intends to produce at analyser angle tau -- i.e. the ground truth Stage 3a
    should recover, before noise.
    """
    tau = math.radians(tau_deg)
    modulation = 0.5 * (1.0 + peak.p1 * math.cos(2 * tau) + peak.p2 * math.sin(2 * tau))
    height = peak.peak_counts * modulation / peak.i0_counts
    # Analytic area of the unit-height pseudo-Voigt, times the height.
    sigma = peak.fwhm_deg / (2.0 * math.sqrt(2.0 * math.log(2.0)))
    area_g = sigma * math.sqrt(2.0 * math.pi)
    area_l = math.pi * peak.fwhm_deg / 2.0
    eta = peak.lorentzian_fraction
    return height * ((1.0 - eta) * area_g + eta * area_l)


# =============================================================================
# SRS FILE WRITER
# =============================================================================

def _srs_text(scan_number: int, peak: SynthPeak, tau_deg: float, pol: str,
              x: np.ndarray, i0: np.ndarray, im: np.ndarray,
              extra_meta: Optional[Dict[str, object]] = None) -> str:
    """
    Build an SRS file whose envelope matches the real I10 files exactly:
    ' &SRS' preamble, <MetaDataAtStart> block, ' &END', column header, rows.
    """
    now = datetime.now()
    meta: Dict[str, object] = {
        "cmd": f"'scan tth {x[0]:.4f} {x[-1]:.4f} "
               f"{(x[1] - x[0]) if x.size > 1 else 0.01:.4f} mcsh16 0.2 mcsh17 0.2'",
        "date": f"'{now.strftime('%a %b %d %H:%M:%S %Y')}'",
        "filepath": f"'./i10-1-{scan_number}.nxs'",
        "filename": f"'i10-1-{scan_number}.nxs'",
        "SYNTHETIC": f"'{SYNTHETIC_BANNER}'",
        "synthetic_generator": f"'rsxd_synth {VERSION}'",
        "synthetic_peak": f"'{peak.name}'",
        "synthetic_P1_prime": f"{peak.p1:.10f}",
        "synthetic_P2_prime": f"{peak.p2:.10f}",
        "synthetic_tau_deg": f"{tau_deg:.6f}",
        "pol": f"'{pol}'",
        "analyser_tau": f"{tau_deg:.6f}",
        "pgm_energy": f"{peak.energy_eV:.4f}",
        "beamenergy": f"{peak.energy_eV:.4f}",
        "demand_field": f"{peak.field_T:.6f}",
        "ips_field": f"{peak.field_T:.6f}",
        "ips_sweeprate": "0.46",
        "itc2": f"{peak.temperature_K:.4f}",
        "itc3": f"{max(peak.temperature_K - 240.0, 4.0):.4f}",
        "sensor_temp": "419.1",
        "sample_name": "'synthetic -- not a real sample'",
        "chemical_formula": "'Undefined'",
        "comment": f"'{SYNTHETIC_BANNER}'",
    }
    if extra_meta:
        meta.update(extra_meta)

    lines = [
        " &SRS",
        f" SRSRUN={scan_number},SRSDAT={now.strftime('%Y%m%d')},"
        f"SRSTIM={now.strftime('%H%M%S')},",
        " SRSSTN='RASOR',SRSPRJ='GDA_BASE',SRSEXP='SYNTHETIC',",
        " SRSTLE='" + SYNTHETIC_BANNER.ljust(60)[:60] + "',",
        " SRSCN1='        ',SRSCN2='        ',SRSCN3='        ',",
        "<MetaDataAtStart>",
    ]
    lines += [f"{k}={v}" for k, v in meta.items()]
    lines += ["</MetaDataAtStart>", " &END", " ".join(SYNTH_COLUMNS)]

    mcsh18 = np.round(i0 * 0.31)          # a plausible third channel
    mcsh19 = np.zeros_like(i0)            # identically zero, as in every real file
    for row in zip(x, i0, im, mcsh18, mcsh19):
        lines.append(" ".join(f"{v:.8f}" for v in row))
    return "\n".join(lines) + "\n"


# =============================================================================
# SERIES GENERATOR
# =============================================================================

@dataclass
class SynthSeries:
    """What was written, and the truth to check the analysis against."""
    peak: SynthPeak
    peak_label: str
    temperature_K: str
    polarisation: str
    taus: List[float]
    scan_numbers: List[int]
    paths: List[Path]
    expected_areas: List[float]
    raw_dir: Path
    # Gain actually applied to each written scan, in the same order as
    # scan_numbers. This is the ground truth the mixed-gain tests check.
    gains: List[Optional[float]] = None


def generate_series(out_dir,
                    peak: SynthPeak,
                    taus: Sequence[float],
                    first_scan: int = 90000,
                    peak_label: str = "Co-tau",
                    temperature_K: str = "300",
                    polarisation: str = "p",
                    n_points: int = 61,
                    half_range_deg: float = 2.0,
                    noise: bool = True,
                    seed: int = 12345,
                    filename_pattern: str = "i10-1-{scan}.dat",
                    gain: float = 1.0,
                    gain_step_at: Optional[int] = None,
                    gain_after: Optional[float] = None) -> SynthSeries:
    """
    Write one full tau series of synthetic theta-2theta SRS files.

    Counting statistics are genuine Poisson draws on BOTH channels, so the
    errors rsxd_analysis computes are the errors actually present -- which is
    what makes "recovered within uncertainty" a meaningful assertion rather
    than a tautology.

    GAIN
    ----
    `gain` multiplies the DETECTOR channel only, exactly as a transimpedance
    amplifier does: the file records photocurrent x gain, and nothing in the
    file says what the gain was. Set `gain_step_at` to a tau index to switch to
    `gain_after` from that scan onward -- this fabricates precisely the failure
    the tracking exists to catch, a step partway through a tau-series that
    looks like dichroism and is not.

    The Poisson draw is taken on the SCALED counts, because that is what the
    real detector-plus-amplifier chain produces: raising the gain genuinely
    raises the recorded counts and genuinely improves the counting statistics.
    """
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)
    rng = np.random.default_rng(seed)

    x = np.linspace(peak.centre_deg - half_range_deg,
                    peak.centre_deg + half_range_deg, n_points)

    scan_numbers, paths, expected, gains = [], [], [], []
    for k, tau in enumerate(taus):
        scan = first_scan + k
        g = gain
        if gain_step_at is not None and gain_after is not None and k >= gain_step_at:
            g = gain_after
        tau_rad = math.radians(tau)
        modulation = 0.5 * (1.0 + peak.p1 * math.cos(2 * tau_rad)
                            + peak.p2 * math.sin(2 * tau_rad))

        profile = _pseudo_voigt(x, peak.centre_deg, peak.fwhm_deg,
                                peak.lorentzian_fraction)
        bkg = peak.background_counts + peak.background_slope * (x - peak.centre_deg)
        # The amplifier scales the detector channel only. I0 has its own
        # (untracked, here constant) chain.
        mean_im = (peak.peak_counts * modulation * profile + bkg) * g
        mean_i0 = np.full_like(x, peak.i0_counts)

        if noise:
            im = rng.poisson(np.clip(mean_im, 0, None)).astype(float)
            i0 = rng.poisson(np.clip(mean_i0, 0, None)).astype(float)
        else:
            im, i0 = mean_im.copy(), mean_i0.copy()

        # NOTE: the gain is deliberately NOT written into the file. That is
        # the whole problem being modelled -- the instrument does not record it.
        text = _srs_text(scan, peak, tau, polarisation, x, i0, im)
        path = out_dir / filename_pattern.replace("{scan}", str(scan))
        _atomic_write(path, text)

        scan_numbers.append(scan)
        paths.append(path)
        gains.append(g)
        expected.append(expected_area(peak, tau) * g)

    return SynthSeries(peak=peak, peak_label=peak_label,
                       temperature_K=str(temperature_K), polarisation=polarisation,
                       taus=list(taus), scan_numbers=scan_numbers, paths=paths,
                       expected_areas=expected, raw_dir=out_dir, gains=gains)


def write_logger_csv(path, series_list: Sequence[SynthSeries]) -> Path:
    """
    Write a phase-1-format cumulative CSV describing the generated series.

    Uses rsxd_core.CSV_COLUMNS directly, so if the frozen schema were ever
    changed this would fail to line up and the self-test would notice.
    """
    path = Path(path)
    rows = []
    for s in series_list:
        gains = s.gains or [None] * len(s.scan_numbers)
        prev = object()
        for tau, scan, g in zip(s.taus, s.scan_numbers, gains):
            # The logger only records a gain where the operator entered one,
            # i.e. at the start and at each change; the rest is forward
            # propagation. Writing it on every row would sidestep the epoch
            # resolver instead of exercising it.
            record = "" if (g is None or g == prev) else fmt_gain(g)
            prev = g
            rows.append({
                "peak": s.peak_label,
                "temperature_K": s.temperature_K,
                "analyser_angle_deg": (str(int(tau)) if float(tau) == int(tau)
                                       else f"{tau:g}"),
                "polarisation": s.polarisation,
                "scan_number": str(scan),
                "note": f"synthetic {s.peak.name}",
                "gain": record,
                "dat_found": "yes",
                "timestamp": datetime.now().isoformat(timespec="seconds"),
            })
    import csv as _csv
    import io as _io
    buf = _io.StringIO(newline="")
    w = _csv.DictWriter(buf, fieldnames=CSV_COLUMNS, lineterminator="\n")
    w.writeheader()
    for r in rows:
        w.writerow(r)
    _atomic_write(path, buf.getvalue())
    return path


def generate_beamtime(root,
                      taus: Optional[Sequence[float]] = None,
                      seed: int = 12345,
                      noise: bool = True) -> Tuple[Path, Path, List[SynthSeries]]:
    """
    Build a complete miniature synthetic beamtime:
      raw_data/           the .dat files
      rsxd_scan_log.csv   the phase-1 index that points at them

    Two series -- one charge-like, one magnetic-like -- so the Stage-4
    comparison and the sign of the discriminator can both be exercised.

    Returns (raw_dir, csv_path, [SynthSeries, ...]).
    """
    root = Path(root)
    raw = root / "raw_data"
    taus = list(taus) if taus is not None else list(range(-90, 91, 15))

    charge = generate_series(raw, CHARGE_PEAK, taus, first_scan=90000,
                             peak_label="Co-tau", temperature_K="300",
                             polarisation="p", seed=seed, noise=noise)
    magnetic = generate_series(raw, MAGNETIC_PEAK, taus, first_scan=91000,
                               peak_label="Fe-tau", temperature_K="300",
                               polarisation="p", seed=seed + 1, noise=noise)

    csv_path = write_logger_csv(root / "rsxd_scan_log.csv", [charge, magnetic])
    return raw, csv_path, [charge, magnetic]


if __name__ == "__main__":
    import sys
    target = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("synthetic_beamtime")
    raw, csv_path, series = generate_beamtime(target)
    print(f"rsxd_synth {VERSION}   (analysis {ANALYSIS_VERSION})")
    print(SYNTHETIC_BANNER)
    print(f"  raw .dat files : {raw}")
    print(f"  logger CSV     : {csv_path}")
    for s in series:
        print(f"  {s.peak_label:8s} {s.peak.name:9s} "
              f"injected P1'={s.peak.p1:+.4f}  P2'={s.peak.p2:+.4f}  "
              f"{len(s.scan_numbers)} scans")
